+/** A cookie jar holding (or missing) the `cart_id` cookie. */
+function jar(value?: string): CookieStore {
+  return {
+    get: () => (value === undefined ? undefined : { name: 'cart_id', value }),
+    set: () => undefined,
+  } as unknown as CookieStore;
+}
+
+describe('readCartId', () => {
+  const id = '123e4567-e89b-42d3-a456-426614174000';
+
+  it('reads a uuid cart id', () => {
+    expect(readCartId(jar(id))).toBe(id);
+  });
+
+  it('treats a missing cookie as no cart', () => {
+    expect(readCartId(jar())).toBeUndefined();
+  });
+
+  it('treats a malformed cookie as no cart', () => {
+    expect(readCartId(jar('42'))).toBeUndefined();
+    expect(readCartId(jar('not-a-uuid'))).toBeUndefined();
+    expect(readCartId(jar(''))).toBeUndefined();
+  });
+});
